import math

def check_prime_power(R, a):
    if R < 2:
        return False

    # Estimate the potential base p
    p_float = R**(1/a)
    p_int = round(p_float)

    # Check if p_int is an integer base
    if abs(p_int**a - R) > 1e-9: # Using tolerance for float comparison, though since R is an integer, exact integer checks should suffice if we use integer root finding.
        p_int = int(math.isqrt(R) if a == 2 else int(round(p_float))) # Simple int rounding
    else:
        p_int = int(p_float)

    # Check if the integer base p_int raised to the power a equals R
    if p_int**a != R:
        return False

    # Check if p_int is prime
    if p_int < 2:
        return False
    for i in range(2, int(math.sqrt(p_int)) + 1):
        if p_int % i == 0:
            return False
    return True

solutions = []
for a in range(1, 11):
    R = 12 * a + 1
    if check_prime_power(R, a):
        # p = R**(1/a)
        p = round(R**(1/a))
        if p**a == R:
             # Final check for primality of p
            is_prime = True
            if p < 2: is_prime = False
            else:
                for i in range(2, int(math.sqrt(p)) + 1):
                    if p % i == 0:
                        is_prime = False
                        break
            if is_prime:
                solutions.append((p, a))

print(solutions)

